199	  // generally the resolved SFCC site ID" — it is not, and must not be assumed correct
200	  // elsewhere by analogy to this lookup.
201	  const {
202	    site,
203	    locale: siteLocale,
204	    buildUrl,
205	  } = useMultiSite() as {
206	    site: { id: string };
207	    locale?: { id: string };
208	    buildUrl: (path: string, siteRef?: string, localeRef?: string) => string;
209	  };
210	  const locale = siteLocale?.id ?? CONTENTFUL_FALLBACK_LOCALE;
211	  const history = useHistory();
212	  const { client } = useContentfulClient();
213	  const [footerData, setFooterData] = useState<FooterConfigEntry | null>(null);
214	
215	  useEffect(() => {
216	    if (!client) return;
217	    let cancelled = false;
218	
219	    // useContentfulClient types the client as ContentfulClientApi<any> for the Experiences
220	    // SDK's benefit — with `any` chain modifiers, EntriesQueries's `locale` field resolves out
221	    // of the type entirely (see useHeaderNav.ts's identical cast for the full explanation).
222	    (client as ContentfulClientApi<undefined>)
223	      .getEntries({ content_type: 'footerConfig', include: FOOTER_INCLUDE_DEPTH, locale })
224	      .then((response) => {
225	        if (cancelled) return;
226	        // The contentful SDK client is loosely typed (see useContentfulClient.ts) —
227	        // FooterConfigEntry mirrors the exact nested-resolved shape `include: 3` produces
228	        // for this content model.
229	        const configs = response.items as unknown as FooterConfigEntry[];
230	        const resolved = pickMostSpecificByRegion<FooterConfigEntry>(configs, site.id);
231	        setFooterData(resolved ? scopeToRegion(resolved, site.id) : null);
232	      })
233	      .catch(() => {
234	        if (!cancelled) setFooterData(null);
235	      });
236	
237	    return () => {
238	      cancelled = true;
239	    };
240	  }, [client, site.id, locale]);
241	
242	  if (!footerData) return null;
243	
244	  return <Footer data={footerData} onLogoClick={() => history.push(buildUrl(HOME_HREF))} {...props} />;
245	};
246	
247	export default FooterContainer;
