import { describe, expect, test } from 'vitest';
import { LANGUAGE_PROMPT_SUPPRESSION_DAYS } from './regionPrefCookie';
import { EU_DOMESTIC_SFCC_SITE_ID, SUPPORTED_EU_LANGUAGES, shouldShowLanguagePrompt } from './shouldShowLanguagePrompt';

const NOW = 1_700_000_000; // an arbitrary fixed epoch-seconds instant
const SECONDS_PER_DAY = 24 * 60 * 60;

const baseInput = {
  sfccSiteId: EU_DOMESTIC_SFCC_SITE_ID,
  currentLanguage: 'it',
  browserLanguages: ['fr-FR'],
  suppressedAt: undefined,
  now: NOW,
};

describe('shouldShowLanguagePrompt — six required branches', () => {
  test('1. non-EU site never shows, regardless of a real language mismatch', () => {
    expect(shouldShowLanguagePrompt({ ...baseInput, sfccSiteId: 'ZimmermannAU' })).toEqual({ show: false });
  });

  test('2. EU site, browser language matches the current site language -> false', () => {
    expect(shouldShowLanguagePrompt({ ...baseInput, currentLanguage: 'it', browserLanguages: ['it-IT'] })).toEqual({
      show: false,
    });
  });

  test('3. EU site, browser language differs and is one of the four -> true, with the right target', () => {
    expect(shouldShowLanguagePrompt({ ...baseInput, currentLanguage: 'it', browserLanguages: ['fr-FR'] })).toEqual({
      show: true,
      targetLanguage: 'fr',
    });
  });

  test('4. EU site, browser language is none of the four -> false', () => {
    expect(shouldShowLanguagePrompt({ ...baseInput, currentLanguage: 'it', browserLanguages: ['de-DE'] })).toEqual({
      show: false,
    });
  });

  test('5. within the suppression window -> false, even though the language would otherwise mismatch', () => {
    const suppressedAt = NOW - 1 * SECONDS_PER_DAY; // dismissed yesterday, well inside 7 days
    expect(shouldShowLanguagePrompt({ ...baseInput, suppressedAt })).toEqual({ show: false });
  });

  test('6. suppression window lapsed -> true again', () => {
    const suppressedAt = NOW - (LANGUAGE_PROMPT_SUPPRESSION_DAYS + 1) * SECONDS_PER_DAY; // 8 days ago
    expect(shouldShowLanguagePrompt({ ...baseInput, suppressedAt })).toEqual({ show: true, targetLanguage: 'fr' });
  });
});

describe('shouldShowLanguagePrompt — primary-subtag extraction, both sides', () => {
  test('fr-FR reduces to fr and matches a bare "fr" current language (would wrongly mismatch on exact string equality)', () => {
    expect(shouldShowLanguagePrompt({ ...baseInput, currentLanguage: 'fr', browserLanguages: ['fr-FR'] })).toEqual({
      show: false,
    });
  });

  test('en-GB (a full tag as the current site language) reduces to en and matches a browser reporting en-AU', () => {
    expect(shouldShowLanguagePrompt({ ...baseInput, currentLanguage: 'en-GB', browserLanguages: ['en-AU'] })).toEqual({
      show: false,
    });
  });
});

describe('shouldShowLanguagePrompt — supporting behaviour', () => {
  test('the suppression window has lapsed by exactly the boundary instant, so the prompt is eligible again (now < end is strict, so now === end already lapses)', () => {
    const suppressedAt = NOW - LANGUAGE_PROMPT_SUPPRESSION_DAYS * SECONDS_PER_DAY;
    // now === suppressedAt + window exactly -> window has *just* lapsed, so it must show again.
    expect(
      shouldShowLanguagePrompt({
        ...baseInput,
        suppressedAt,
        now: suppressedAt + LANGUAGE_PROMPT_SUPPRESSION_DAYS * SECONDS_PER_DAY,
      }),
    ).toEqual({
      show: true,
      targetLanguage: 'fr',
    });
  });

  test('an empty browserLanguages array never throws and never shows', () => {
    expect(() => shouldShowLanguagePrompt({ ...baseInput, browserLanguages: [] })).not.toThrow();
    expect(shouldShowLanguagePrompt({ ...baseInput, browserLanguages: [] })).toEqual({ show: false });
  });

  test('SUPPORTED_EU_LANGUAGES is exactly the four EU-domestic primary languages', () => {
    expect(SUPPORTED_EU_LANGUAGES).toEqual(['en', 'fr', 'it', 'es']);
  });
});

#!/usr/bin/env node
/**
 * One-off seed script — creates the 1 uiCopy entry for ZimmDrawer's close button label
 * (SFCC-831, discovered as a gap while seeding the regional prompt keys — see
 * ~/Dev/zimmerMANN-skills/.runs/SFCC-831/decisions.md for the full history).
 *
 * Usage:
 *   node scripts/contentful/seedDrawerCloseUiCopy.mjs --target dev
 *
 * Targets a single Contentful environment. Defaults to 'dev' if --target is omitted.
 * Skips the entry if its key already exists in the target environment (safe to re-run).
 * The entry is created AND published in one pass.
 *
 * Required env vars (from .env via `npm run env -- init`):
 *   CONTENTFUL_MANAGEMENT_TOKEN
 *   CONTENTFUL_SPACE_ID
 *
 * The value below must match zimmDrawer/index.tsx's `t('drawer.close', 'Close')` call
 * exactly — that component's own inline fallback is the source of truth this script mirrors,
 * not the other way round. This one key is shared by all four ZimmDrawer consumers (the PDP
 * tab drawer, the Wishlist/Login drawer, Find in Boutique, and the regional country/language
 * mismatch prompt) — until this entry is seeded, every one of them renders the English
 * "Close" fallback on every locale, including the EU-domestic sites this build's own feature
 * is meant to speak the right language on.
 */

import { checkEnv, createClient, log, resolveTarget, seedUiCopyEntries } from './setup/_shared.mjs';

const TARGET = resolveTarget();

checkEnv(['CONTENTFUL_MANAGEMENT_TOKEN', 'CONTENTFUL_SPACE_ID']);

/** @type {{ key: string; title: string; value: string; description: string }[]} */
const ENTRIES = [
  {
    key: 'drawer.close',
    title: 'Drawer — Close Button Label',
    value: 'Close',
    description:
      "Accessible label (aria-label) for the close (X) button on every ZimmDrawer instance " +
      "site-wide — the PDP tab drawer, the Wishlist/Login drawer, Find in Boutique, and the " +
      "regional country/language mismatch prompt all share this one key. Read aloud by screen " +
      "readers; not visible text in the UI. No tokens.",
  },
];

seedUiCopyEntries(createClient(), TARGET, ENTRIES).catch((err) => {
  log.error(err.message ?? String(err));
  process.exit(1);
});

